        case .off:
            // No vibration
            break
        case .soft:
            // Use UIImpactFeedbackGenerator for more reliable soft feedback
            let softImpact = UIImpactFeedbackGenerator(style: .light)
            softImpact.prepare()
            softImpact.impactOccurred()

            // Add AudioServices as backup on older devices
            AudioServicesPlaySystemSound(1520)
