        // Vertical center line
        path.move(to: CGPoint(x: w * 0.5, y: 0))
        path.addLine(to: CGPoint(x: w * 0.5, y: h))

        // Upper path: top-center → right-mid-upper → left-mid-lower
        path.move(to: CGPoint(x: w * 0.5, y: 0))
        path.addLine(to: CGPoint(x: w * 0.85, y: h * 0.3))
        path.addLine(to: CGPoint(x: w * 0.15, y: h * 0.7))

        // Lower path: bottom-center → right-mid-lower → left-mid-upper
        path.move(to: CGPoint(x: w * 0.5, y: h))
        path.addLine(to: CGPoint(x: w * 0.85, y: h * 0.7))
        path.addLine(to: CGPoint(x: w * 0.15, y: h * 0.3))

        return path
    }
}

