    // Check if a DisplayableSound belongs to a focus group
    func isSoundInFocusGroup(_ sound: DisplayableSound, group: FocusGroup) -> Bool {
        // Check each underlying sound against the group's sound list
        // Check both displayName and labelName to handle localization
        for underlying in sound.underlyingSounds {
            if group.sounds.contains(underlying.displayName) {
                return true
            }
            // Also check the raw label name (handles localization mismatches)
            let rawLabel = underlying.labelName.replacingOccurrences(of: "_", with: " ").capitalized
            if group.sounds.contains(rawLabel) {
                return true
            }
        }
        // Also check the DisplayableSound's id (which is the raw label for individual sounds)
        if group.sounds.contains(sound.id) {
            return true
        }
        // Also check if it's a grouped sound (e.g., "Emergency Sirens") where members overlap
        if let groupMembers = soundGroups[sound.displayName] {
            for member in groupMembers {
                if group.sounds.contains(member) {
                    return true
                }
            }
        }
        return false
    }

    // Get the active focus group if one is selected
    var activeFocusGroup: FocusGroup? {
        guard let id = activeFocusGroupId else { return nil }
        return allFocusGroups.first { $0.id == id }
    }

    // Get sounds grouped by category
    func getGroupedSoundsByCategory() -> [String: [DisplayableSound]] {
        let allSounds = getDisplayableSounds()
        var grouped: [String: [DisplayableSound]] = [:]

        for sound in allSounds {
            let category = getCategoryForSound(sound.displayName)
            if grouped[category] == nil {
                grouped[category] = []
            }
            grouped[category]?.append(sound)
        }

        // Sort sounds within each category alphabetically
        for (category, sounds) in grouped {
            grouped[category] = sounds.sorted { $0.displayName < $1.displayName }
        }

        return grouped
    }
