    private func severity(for soundLabel: String) -> SoundSeverity {
        let normalized = soundLabel.lowercased()
        let criticalLabels: Set<String> = [
            "smoke detector",
            "fire/smoke detector",
            "civil defense siren",
            "emergency sirens",
            "emergency vehicle",
            "fire engine siren",
            "police siren",
            "ambulance siren",
            "glass breaking",
            "alarm clock"
        ]
        let importantLabels: Set<String> = [
            "door bell",
            "knock",
            "baby crying",
            "telephone bell ringing",
            "phone ringing",
            "water tap faucet",
            "water running",
            "microwave oven",
            "car horn"
        ]

        if criticalLabels.contains(normalized) {
            return .critical
        }
        if importantLabels.contains(normalized) {
            return .important
        }
        return .informational
    }

