    private func isSoundInSemanticMode(_ sound: DisplayableSound, mode: SemanticFocusMode) -> Bool {
        if severity(for: sound.displayName) == mode.severity {
            return true
        }
        for underlying in sound.underlyingSounds where severity(for: underlying.displayName) == mode.severity {
            return true
        }
        return false
    }

    private func applySemanticFocusMode(_ mode: SemanticFocusMode) {
        if activeFocusGroupId == mode.storageId {
            activeFocusGroupId = nil
            saveActiveFocusSelection()
            return
        }

        selectedSounds.removeAll()
        let displayableSounds = getDisplayableSounds().filter { isSoundInSemanticMode($0, mode: mode) }
        for displayable in displayableSounds {
            for underlying in displayable.underlyingSounds {
                if globalState.isSubscribed || !isPremiumSound(underlying.displayName) {
                    selectedSounds.insert(underlying)
                }
            }
        }

        activeFocusGroupId = mode.storageId
        saveSelectedSounds()
        saveActiveFocusSelection()
        appState.updateSelectedSounds(selectedSounds)
    }

